"""PHP, JavaScript and networking answers. Code is wrapped in `backticks`. Original explanations, four languages
(fr/rw/sw are drafts until reviewed). Technical terms stay in English on purpose."""
from knowledge_base import _e

ENTRIES_CODE = [
_e("php_basics", ["php_arrays_loops", "php_form_post", "learn_programming"],
   ("How do I start with PHP (Hello World and variables)?", "Comment débuter avec PHP (Hello World et variables) ?", "Natangira nte PHP (Hello World n'ibihinduka)?", "Ninawezaje kuanza na PHP (Hello World na vigeuzo)?"),
   ("php|php basics|php hello world|php variables|learn php|what is php|php echo|php tutorial|php for beginners|run php",
    "php|bases de php|php hello world|variables php|apprendre php|qu'est-ce que php|php echo|tutoriel php|php pour debutants|executer php",
    "php|ibanze bya php|php hello world|variables za php|kwiga php|php ni iki|php echo|php y'abatangiye|gukoresha php",
    "php|misingi ya php|php hello world|vigeuzo vya php|kujifunza php|php ni nini|php echo|php kwa wanaoanza|kuendesha php"),
   ("PHP is a server-side scripting language used to build dynamic websites. PHP code lives between `<?php` and `?>`, ends statements with `;`, and variables start with `$`. The server runs the code and sends plain HTML to the browser.",
    "PHP est un langage de script côté serveur utilisé pour créer des sites dynamiques. Le code PHP se place entre `<?php` et `?>`, chaque instruction finit par `;` et les variables commencent par `$`. Le serveur exécute le code et envoie du HTML au navigateur.",
    "PHP ni ururimi rw'ubwanditsi ruhagarara kuri seriveri rukoreshwa mu kubaka imbuga zihinduka. Code ya PHP iba hagati ya `<?php` na `?>`, buri nteruro irangirwa na `;`, kandi variables zitangirana na `$`. Seriveri ikoresha code igaha browser HTML.",
    "PHP ni lugha ya hati inayoendeshwa upande wa seva inayotumika kujenga tovuti zenye mabadiliko. Msimbo wa PHP uko kati ya `<?php` na `?>`, kila amri huishia na `;`, na vigeuzo huanza na `$`. Seva huendesha msimbo na kutuma HTML kwa kivinjari."),
   (["Hello World: `<?php echo \"Hello, World!\"; ?>`", "Variable: `$name = \"Aline\"; echo \"Hello $name\";`", "Run locally with XAMPP, or in a terminal: `php -S localhost:8000`", "Save the file as `index.php`; opening it directly as a plain file will not run the PHP."],
    ["Hello World : `<?php echo \"Hello, World!\"; ?>`", "Variable : `$name = \"Aline\"; echo \"Hello $name\";`", "Exécutez en local avec XAMPP, ou dans un terminal : `php -S localhost:8000`", "Enregistrez en `index.php` ; ouvrir le fichier directement ne l'exécute pas."],
    ["Hello World: `<?php echo \"Hello, World!\"; ?>`", "Variable: `$name = \"Aline\"; echo \"Hello $name\";`", "Koresha kuri mudasobwa yawe ukoresheje XAMPP, cyangwa muri terminal: `php -S localhost:8000`", "Bika idosiye nka `index.php`; kuyifungura nk'idosiye isanzwe ntibikora PHP."],
    ["Hello World: `<?php echo \"Hello, World!\"; ?>`", "Kigeuzo: `$name = \"Aline\"; echo \"Hello $name\";`", "Endesha kwenye kompyuta kwa XAMPP, au kwenye terminal: `php -S localhost:8000`", "Hifadhi faili kama `index.php`; kuifungua moja kwa moja haiendeshi PHP."])),

_e("php_arrays_loops", ["php_basics", "php_form_post", "js_array_methods"],
   ("How do arrays and loops work in PHP?", "Comment fonctionnent les tableaux et les boucles en PHP ?", "Arrays na loops bikora bite muri PHP?", "Arrays na loops hufanyaje kazi katika PHP?"),
   ("php array|php arrays|php loop|php foreach|php for loop|php while loop|associative array php|php count|php loop through array|php if else",
    "tableau php|tableaux php|boucle php|php foreach|boucle for php|boucle while php|tableau associatif php|php count|parcourir un tableau php|php if else",
    "array ya php|arrays za php|loop ya php|php foreach|loop ya for muri php|loop ya while muri php|associative array php|php count",
    "array ya php|arrays za php|kitanzi cha php|php foreach|kitanzi cha for php|kitanzi cha while php|associative array php|php count"),
   ("An array holds many values. Loop over it with `foreach`. An associative array uses named keys instead of numbers.",
    "Un tableau contient plusieurs valeurs. Parcourez-le avec `foreach`. Un tableau associatif utilise des clés nommées au lieu de numéros.",
    "Array ibika indangagaciro nyinshi. Uyinyuzemo ukoresheje `foreach`. Associative array ikoresha amazina y'ibisobanuro aho gukoresha imibare.",
    "Array hushika thamani nyingi. Pita ndani yake kwa `foreach`. Associative array hutumia funguo zenye majina badala ya namba."),
   (["List: `$fruits = [\"mango\", \"banana\", \"avocado\"];`", "Loop: `foreach ($fruits as $f) { echo $f . \"<br>\"; }`", "Associative: `$user = [\"name\" => \"Aline\", \"age\" => 21]; echo $user[\"name\"];`", "Count items: `count($fruits)`; condition: `if ($age >= 18) { ... } else { ... }`"],
    ["Liste : `$fruits = [\"mango\", \"banana\", \"avocado\"];`", "Boucle : `foreach ($fruits as $f) { echo $f . \"<br>\"; }`", "Associatif : `$user = [\"name\" => \"Aline\", \"age\" => 21]; echo $user[\"name\"];`", "Compter : `count($fruits)` ; condition : `if ($age >= 18) { ... } else { ... }`"],
    ["Urutonde: `$fruits = [\"mango\", \"banana\", \"avocado\"];`", "Loop: `foreach ($fruits as $f) { echo $f . \"<br>\"; }`", "Associative: `$user = [\"name\" => \"Aline\", \"age\" => 21]; echo $user[\"name\"];`", "Kubara: `count($fruits)`; condition: `if ($age >= 18) { ... } else { ... }`"],
    ["Orodha: `$fruits = [\"mango\", \"banana\", \"avocado\"];`", "Kitanzi: `foreach ($fruits as $f) { echo $f . \"<br>\"; }`", "Associative: `$user = [\"name\" => \"Aline\", \"age\" => 21]; echo $user[\"name\"];`", "Kuhesabu: `count($fruits)`; sharti: `if ($age >= 18) { ... } else { ... }`"])),

_e("php_form_post", ["php_pdo_prepared", "php_basics", "php_session"],
   ("How do I read a form in PHP safely?", "Comment lire un formulaire en PHP en toute sécurité ?", "Nasoma nte form muri PHP mu buryo butekanye?", "Ninawezaje kusoma fomu katika PHP kwa usalama?"),
   ("php form|php post|php _post|php get|read form data php|php form handling|php html form|php validate input|php xss|htmlspecialchars",
    "formulaire php|php post|php _post|php get|lire les donnees d'un formulaire php|traitement de formulaire php|valider les entrees php|php xss|htmlspecialchars",
    "form ya php|php post|php _post|php get|gusoma amakuru ya form muri php|kugenzura ibyinjijwe php|php xss|htmlspecialchars",
    "fomu ya php|php post|php _post|php get|kusoma data ya fomu php|kuhakiki ingizo php|php xss|htmlspecialchars"),
   ("Send the form with `method=\"post\"`, read values from `$_POST`, check them, and always escape anything you print back with `htmlspecialchars()` to stop cross-site scripting (XSS). Never trust user input.",
    "Envoyez le formulaire avec `method=\"post\"`, lisez les valeurs dans `$_POST`, vérifiez-les et échappez toujours ce que vous réaffichez avec `htmlspecialchars()` pour empêcher le XSS. Ne faites jamais confiance aux entrées utilisateur.",
    "Ohereza form ukoresheje `method=\"post\"`, usome indangagaciro muri `$_POST`, uzigenzure, kandi burigihe ukoreshe `htmlspecialchars()` ku byo ugaragaza kugira ngo wirinde XSS. Ntukizere ibyinjijwe n'umukoresha.",
    "Tuma fomu kwa `method=\"post\"`, soma thamani kutoka `$_POST`, zihakiki, na kila mara tumia `htmlspecialchars()` kwa chochote unachoonyesha ili kuzuia XSS. Kamwe usiamini ingizo la mtumiaji."),
   (["HTML: `<form method=\"post\" action=\"save.php\"><input name=\"name\"><button>Send</button></form>`", "PHP: `$name = trim($_POST[\"name\"] ?? \"\");`", "Validate: `if ($name === \"\") { echo \"Name is required\"; }`", "Output safely: `echo htmlspecialchars($name, ENT_QUOTES, \"UTF-8\");`"],
    ["HTML : `<form method=\"post\" action=\"save.php\"><input name=\"name\"><button>Send</button></form>`", "PHP : `$name = trim($_POST[\"name\"] ?? \"\");`", "Valider : `if ($name === \"\") { echo \"Name is required\"; }`", "Sortie sûre : `echo htmlspecialchars($name, ENT_QUOTES, \"UTF-8\");`"],
    ["HTML: `<form method=\"post\" action=\"save.php\"><input name=\"name\"><button>Send</button></form>`", "PHP: `$name = trim($_POST[\"name\"] ?? \"\");`", "Kugenzura: `if ($name === \"\") { echo \"Name is required\"; }`", "Gutanga umusaruro utekanye: `echo htmlspecialchars($name, ENT_QUOTES, \"UTF-8\");`"],
    ["HTML: `<form method=\"post\" action=\"save.php\"><input name=\"name\"><button>Send</button></form>`", "PHP: `$name = trim($_POST[\"name\"] ?? \"\");`", "Kuhakiki: `if ($name === \"\") { echo \"Name is required\"; }`", "Matokeo salama: `echo htmlspecialchars($name, ENT_QUOTES, \"UTF-8\");`"])),

_e("php_pdo_prepared", ["php_form_post", "php_session", "strong_passwords"],
   ("How do I use a database in PHP without SQL injection?", "Comment utiliser une base de données en PHP sans injection SQL ?", "Nakoresha nte database muri PHP nta SQL injection?", "Ninawezaje kutumia hifadhidata katika PHP bila SQL injection?"),
   ("php mysql|php pdo|php database|sql injection|prepared statement|php prepared statements|php password hash|password_hash|php connect to mysql|php login",
    "php mysql|php pdo|base de donnees php|injection sql|requete preparee|requetes preparees php|hachage mot de passe php|password_hash|connexion mysql php|connexion php",
    "php mysql|php pdo|database ya php|sql injection|prepared statement|php password hash|password_hash|guhuza php na mysql",
    "php mysql|php pdo|hifadhidata ya php|sql injection|prepared statement|php password hash|password_hash|kuunganisha php na mysql"),
   ("Use PDO with prepared statements: the SQL and the data travel separately, so user input can never change the query. Never build SQL by joining strings with user input. Store passwords with `password_hash()`, never as plain text.",
    "Utilisez PDO avec des requêtes préparées : le SQL et les données voyagent séparément, donc l'entrée de l'utilisateur ne peut pas modifier la requête. Ne construisez jamais du SQL en concaténant des entrées. Stockez les mots de passe avec `password_hash()`, jamais en clair.",
    "Koresha PDO ufite prepared statements: SQL n'amakuru bigenda ukwayo, bityo ibyinjijwe n'umukoresha ntibishobora guhindura query. Ntukubake SQL uhuje inyandiko n'ibyinjijwe. Bika amagambo y'ibanga ukoresheje `password_hash()`, ntabwo ari mu buryo busomeka.",
    "Tumia PDO na prepared statements: SQL na data husafiri tofauti, kwa hiyo ingizo la mtumiaji haliwezi kubadilisha query. Usijenge SQL kwa kuunganisha maandishi na ingizo. Hifadhi nenosiri kwa `password_hash()`, kamwe si kwa maandishi wazi."),
   (["Connect: `$pdo = new PDO(\"mysql:host=localhost;dbname=app;charset=utf8mb4\", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);`", "Query: `$stmt = $pdo->prepare(\"SELECT * FROM users WHERE email = ?\"); $stmt->execute([$email]); $row = $stmt->fetch();`", "Save a password: `$hash = password_hash($password, PASSWORD_DEFAULT);` and check: `password_verify($input, $hash)`", "Keep database passwords out of public code and out of GitHub."],
    ["Connexion : `$pdo = new PDO(\"mysql:host=localhost;dbname=app;charset=utf8mb4\", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);`", "Requête : `$stmt = $pdo->prepare(\"SELECT * FROM users WHERE email = ?\"); $stmt->execute([$email]); $row = $stmt->fetch();`", "Enregistrer un mot de passe : `$hash = password_hash($password, PASSWORD_DEFAULT);` et vérifier : `password_verify($input, $hash)`", "Gardez les mots de passe de base de données hors du code public et de GitHub."],
    ["Guhuza: `$pdo = new PDO(\"mysql:host=localhost;dbname=app;charset=utf8mb4\", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);`", "Query: `$stmt = $pdo->prepare(\"SELECT * FROM users WHERE email = ?\"); $stmt->execute([$email]); $row = $stmt->fetch();`", "Kubika ijambo ry'ibanga: `$hash = password_hash($password, PASSWORD_DEFAULT);` no kugenzura: `password_verify($input, $hash)`", "Ntushyire amagambo y'ibanga ya database mu code rusange cyangwa kuri GitHub."],
    ["Kuunganisha: `$pdo = new PDO(\"mysql:host=localhost;dbname=app;charset=utf8mb4\", $user, $pass, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);`", "Query: `$stmt = $pdo->prepare(\"SELECT * FROM users WHERE email = ?\"); $stmt->execute([$email]); $row = $stmt->fetch();`", "Hifadhi nenosiri: `$hash = password_hash($password, PASSWORD_DEFAULT);` na ukague: `password_verify($input, $hash)`", "Weka nenosiri za hifadhidata mbali na msimbo wa umma na GitHub."])),

_e("php_session", ["php_pdo_prepared", "php_form_post", "two_step"],
   ("How do PHP sessions and login work?", "Comment fonctionnent les sessions et la connexion en PHP ?", "Sessions na login bikora bite muri PHP?", "Sessions na kuingia hufanyaje kazi katika PHP?"),
   ("php session|php sessions|session_start|php login system|php logout|php cookie|session_destroy|keep user logged in php|php authentication",
    "session php|sessions php|session_start|systeme de connexion php|deconnexion php|cookie php|session_destroy|garder l'utilisateur connecte php|authentification php",
    "session ya php|sessions za php|session_start|login muri php|logout muri php|cookie ya php|session_destroy|kwemeza umukoresha php",
    "session ya php|sessions za php|session_start|mfumo wa kuingia php|kutoka php|cookie ya php|session_destroy|uthibitishaji php"),
   ("A session lets the server remember a user between pages. Call `session_start()` before any output, store the user id in `$_SESSION`, and clear it on logout. Regenerate the session id after login.",
    "Une session permet au serveur de se souvenir d'un utilisateur entre les pages. Appelez `session_start()` avant toute sortie, stockez l'identifiant dans `$_SESSION` et videz-la à la déconnexion. Régénérez l'identifiant de session après la connexion.",
    "Session ituma seriveri yibuka umukoresha hagati y'impapuro. Hamagara `session_start()` mbere y'ibisohoka byose, bika id y'umukoresha muri `$_SESSION`, uyisibe iyo asohotse. Ongera ukore id nshya ya session nyuma yo kwinjira.",
    "Session humruhusu seva kumkumbuka mtumiaji kati ya kurasa. Ita `session_start()` kabla ya matokeo yoyote, hifadhi kitambulisho cha mtumiaji kwenye `$_SESSION`, na kifute anapotoka. Tengeneza kitambulisho kipya cha session baada ya kuingia."),
   (["Start: `session_start();` at the very top of every page that needs it.", "After checking the password: `session_regenerate_id(true); $_SESSION[\"user_id\"] = $id;`", "Protect a page: `if (!isset($_SESSION[\"user_id\"])) { header(\"Location: login.php\"); exit; }`", "Logout: `$_SESSION = []; session_destroy();`"],
    ["Début : `session_start();` tout en haut de chaque page concernée.", "Après vérification du mot de passe : `session_regenerate_id(true); $_SESSION[\"user_id\"] = $id;`", "Protéger une page : `if (!isset($_SESSION[\"user_id\"])) { header(\"Location: login.php\"); exit; }`", "Déconnexion : `$_SESSION = []; session_destroy();`"],
    ["Tangira: `session_start();` hejuru cyane ya buri paji ibikeneye.", "Nyuma yo kugenzura ijambo ry'ibanga: `session_regenerate_id(true); $_SESSION[\"user_id\"] = $id;`", "Kurinda paji: `if (!isset($_SESSION[\"user_id\"])) { header(\"Location: login.php\"); exit; }`", "Gusohoka: `$_SESSION = []; session_destroy();`"],
    ["Anza: `session_start();` juu kabisa ya kila ukurasa unaohitaji.", "Baada ya kuhakiki nenosiri: `session_regenerate_id(true); $_SESSION[\"user_id\"] = $id;`", "Linda ukurasa: `if (!isset($_SESSION[\"user_id\"])) { header(\"Location: login.php\"); exit; }`", "Kutoka: `$_SESSION = []; session_destroy();`"])),

_e("js_variables", ["js_arrow_functions", "js_equality", "learn_programming"],
   ("What is the difference between let, const and var in JavaScript?", "Quelle différence entre let, const et var en JavaScript ?", "Itandukaniro rya let, const na var muri JavaScript ni irihe?", "Tofauti ya let, const na var katika JavaScript ni ipi?"),
   ("javascript|js variables|let const and var|let and const|difference between let|let const var|let vs const|var vs let|javascript variable|declare a variable javascript|what is let in javascript|const in javascript|javascript scope",
    "javascript|variables js|let const var|let ou const|var ou let|variable javascript|declarer une variable javascript|portee javascript|const en javascript",
    "javascript|variables za js|let const var|let cyangwa const|var cyangwa let|variable muri javascript|scope ya javascript",
    "javascript|vigeuzo vya js|let const var|let au const|var au let|kigeuzo katika javascript|wigo wa javascript|const katika javascript"),
   ("`let` declares a variable you can change, `const` declares one that cannot be reassigned, and `var` is the old function-scoped style that is best avoided. Both `let` and `const` are block-scoped (they exist only inside the `{ }` where they are declared).",
    "`let` déclare une variable modifiable, `const` une variable non réassignable et `var` est l'ancien style à portée de fonction, à éviter. `let` et `const` ont une portée de bloc (elles n'existent que dans les `{ }` où elles sont déclarées).",
    "`let` itangaza variable ushobora guhindura, `const` itangaza itongera guhabwa agaciro gashya, naho `var` ni uburyo bwa kera bukorera ku rwego rwa function bukwiye kwirindwa. `let` na `const` bikorera mu `{ }` byatangarijwemo gusa.",
    "`let` hutangaza kigeuzo unachoweza kubadilisha, `const` kisichoweza kupewa thamani mpya, na `var` ni mtindo wa zamani wa wigo wa function unaofaa kuepukwa. `let` na `const` hufanya kazi ndani ya `{ }` zilizotangazwa tu."),
   (["`let count = 1; count = 2;` works.", "`const name = \"Aline\"; name = \"Eric\";` throws a TypeError.", "A `const` array or object can still change inside: `const a = []; a.push(1);` is fine.", "Rule of thumb: use `const` by default, `let` when the value must change."],
    ["`let count = 1; count = 2;` fonctionne.", "`const name = \"Aline\"; name = \"Eric\";` lève une TypeError.", "Un tableau ou objet `const` peut changer de contenu : `const a = []; a.push(1);` est valide.", "Règle simple : `const` par défaut, `let` quand la valeur doit changer."],
    ["`let count = 1; count = 2;` irakora.", "`const name = \"Aline\"; name = \"Eric\";` itanga TypeError.", "Array cyangwa object ya `const` ishobora guhindura ibiyirimo: `const a = []; a.push(1);` ni byiza.", "Itegeko ry'ibanze: koresha `const` mbere na mbere, `let` iyo agaciro kagomba guhinduka."],
    ["`let count = 1; count = 2;` inafanya kazi.", "`const name = \"Aline\"; name = \"Eric\";` hutoa TypeError.", "Array au object ya `const` bado inaweza kubadilika ndani: `const a = []; a.push(1);` ni sawa.", "Kanuni: tumia `const` kwanza, `let` thamani inapohitaji kubadilika."])),

_e("js_arrow_functions", ["js_variables", "js_array_methods", "js_equality"],
   ("What are functions and arrow functions in JavaScript?", "Que sont les fonctions et les fonctions fléchées en JavaScript ?", "Functions na arrow functions muri JavaScript ni iki?", "Functions na arrow functions katika JavaScript ni nini?"),
   ("javascript function|js function|arrow function|arrow functions|what is an arrow function|define a function javascript|function expression|callback function|javascript this|fat arrow",
    "fonction javascript|fonction js|fonction fleche|fonctions flechees|qu'est-ce qu'une fonction flechee|definir une fonction javascript|fonction de rappel|callback|javascript this",
    "function ya javascript|function ya js|arrow function|arrow functions|arrow function ni iki|gusobanura function muri javascript|callback function",
    "function ya javascript|function ya js|arrow function|arrow functions|arrow function ni nini|kufafanua function katika javascript|callback function"),
   ("A function is a reusable block of code. An arrow function is a shorter way to write one: `const add = (a, b) => a + b;`. Arrow functions are handy as callbacks, and unlike normal functions they do not have their own `this`.",
    "Une fonction est un bloc de code réutilisable. Une fonction fléchée est une écriture plus courte : `const add = (a, b) => a + b;`. Elles sont pratiques comme callbacks et, contrairement aux fonctions classiques, n'ont pas leur propre `this`.",
    "Function ni igice cya code gishobora gukoreshwa kenshi. Arrow function ni uburyo bugufi bwo kuyandika: `const add = (a, b) => a + b;`. Ziba zifite akamaro nka callbacks kandi zitandukanye na function zisanzwe kuko zitagira `this` yazo.",
    "Function ni kipande cha msimbo kinachoweza kutumika tena. Arrow function ni njia fupi ya kuiandika: `const add = (a, b) => a + b;`. Ni muhimu kama callbacks na tofauti na function za kawaida hazina `this` yake yenyewe."),
   (["Normal: `function add(a, b) { return a + b; }`", "Arrow: `const add = (a, b) => a + b;` then `add(2, 3)` returns 5.", "One parameter needs no brackets: `const double = x => x * 2;`", "Use a block body when you need several lines: `(a, b) => { const s = a + b; return s; }`"],
    ["Classique : `function add(a, b) { return a + b; }`", "Fléchée : `const add = (a, b) => a + b;` puis `add(2, 3)` renvoie 5.", "Un seul paramètre sans parenthèses : `const double = x => x * 2;`", "Avec plusieurs lignes, utilisez un bloc : `(a, b) => { const s = a + b; return s; }`"],
    ["Isanzwe: `function add(a, b) { return a + b; }`", "Arrow: `const add = (a, b) => a + b;` hanyuma `add(2, 3)` isubiza 5.", "Parameter imwe nta makaramu: `const double = x => x * 2;`", "Iyo ukeneye imirongo myinshi koresha blok: `(a, b) => { const s = a + b; return s; }`"],
    ["Ya kawaida: `function add(a, b) { return a + b; }`", "Arrow: `const add = (a, b) => a + b;` kisha `add(2, 3)` inarudisha 5.", "Parameter moja haihitaji mabano: `const double = x => x * 2;`", "Ukihitaji mistari mingi tumia blok: `(a, b) => { const s = a + b; return s; }`"])),

_e("js_array_methods", ["js_arrow_functions", "js_dom_events", "php_arrays_loops"],
   ("How do map, filter and reduce work on arrays?", "Comment fonctionnent map, filter et reduce sur les tableaux ?", "map, filter na reduce bikora bite kuri array?", "map, filter na reduce hufanyaje kazi kwenye array?"),
   ("javascript map|javascript filter|javascript reduce|array methods|js array methods|map filter reduce|foreach javascript|array push pop|loop through array javascript|find in array javascript",
    "javascript map|javascript filter|javascript reduce|methodes de tableau|methodes de tableau js|map filter reduce|foreach javascript|push pop tableau|parcourir un tableau javascript|trouver dans un tableau javascript",
    "javascript map|javascript filter|javascript reduce|imikorere ya array|map filter reduce|foreach javascript|push pop|gusoma array muri javascript",
    "javascript map|javascript filter|javascript reduce|njia za array|map filter reduce|foreach javascript|push pop|kupitia array katika javascript"),
   ("`map` makes a new array by changing every item, `filter` keeps only the items that pass a test, and `reduce` combines all items into one value. None of them change the original array.",
    "`map` crée un nouveau tableau en transformant chaque élément, `filter` garde seulement les éléments qui passent un test et `reduce` combine tous les éléments en une valeur. Aucune ne modifie le tableau d'origine.",
    "`map` ikora array nshya ihindura buri kintu, `filter` igumana ibyatsinze ikizamini gusa, naho `reduce` ihuza ibintu byose mu gaciro kamwe. Nta na kimwe muri byo gihindura array y'umwimerere.",
    "`map` huunda array mpya kwa kubadilisha kila kipengee, `filter` huweka vinavyopita jaribio tu, na `reduce` huunganisha vipengee vyote kuwa thamani moja. Hakuna kati yao kinachobadilisha array asilia."),
   (["`[1, 2, 3].map(x => x * 2)` → `[2, 4, 6]`", "`[1, 2, 3].filter(x => x > 1)` → `[2, 3]`", "`[1, 2, 3].reduce((sum, x) => sum + x, 0)` → `6`", "Also: `arr.push(4)` adds, `arr.pop()` removes the last, `arr.find(x => x > 1)` returns the first match."],
    ["`[1, 2, 3].map(x => x * 2)` → `[2, 4, 6]`", "`[1, 2, 3].filter(x => x > 1)` → `[2, 3]`", "`[1, 2, 3].reduce((sum, x) => sum + x, 0)` → `6`", "Aussi : `arr.push(4)` ajoute, `arr.pop()` retire le dernier, `arr.find(x => x > 1)` renvoie le premier résultat."],
    ["`[1, 2, 3].map(x => x * 2)` → `[2, 4, 6]`", "`[1, 2, 3].filter(x => x > 1)` → `[2, 3]`", "`[1, 2, 3].reduce((sum, x) => sum + x, 0)` → `6`", "Kandi: `arr.push(4)` yongeraho, `arr.pop()` ikuraho icya nyuma, `arr.find(x => x > 1)` isubiza icya mbere gihuye."],
    ["`[1, 2, 3].map(x => x * 2)` → `[2, 4, 6]`", "`[1, 2, 3].filter(x => x > 1)` → `[2, 3]`", "`[1, 2, 3].reduce((sum, x) => sum + x, 0)` → `6`", "Pia: `arr.push(4)` huongeza, `arr.pop()` huondoa cha mwisho, `arr.find(x => x > 1)` hurudisha cha kwanza kinacholingana."])),

_e("js_dom_events", ["js_array_methods", "js_fetch", "js_equality"],
   ("How do I change a web page and react to clicks with JavaScript?", "Comment modifier une page web et réagir aux clics avec JavaScript ?", "Nahindura nte paji y'urubuga nkakira ibyo ukanze na JavaScript?", "Ninawezaje kubadilisha ukurasa wa wavuti na kuitikia mibofyo kwa JavaScript?"),
   ("dom|javascript dom|addeventlistener|javascript click event|queryselector|change text javascript|get element javascript|javascript button click|innerhtml|textcontent",
    "dom|dom javascript|addeventlistener|evenement clic javascript|queryselector|changer le texte javascript|recuperer un element javascript|clic sur un bouton javascript|innerhtml|textcontent",
    "dom|dom ya javascript|addeventlistener|kanda javascript|queryselector|guhindura inyandiko javascript|gufata element javascript|akabuto javascript|innerhtml|textcontent",
    "dom|dom ya javascript|addeventlistener|tukio la kubofya javascript|queryselector|kubadilisha maandishi javascript|kupata kipengee javascript|kitufe javascript|innerhtml|textcontent"),
   ("The DOM is the page as JavaScript sees it. Select an element with `document.querySelector()`, change it, and react to actions with `addEventListener()`. Use `textContent` (not `innerHTML`) for text from users, to avoid injecting code.",
    "Le DOM est la page telle que JavaScript la voit. Sélectionnez un élément avec `document.querySelector()`, modifiez-le et réagissez aux actions avec `addEventListener()`. Utilisez `textContent` (pas `innerHTML`) pour le texte venant des utilisateurs, afin d'éviter l'injection de code.",
    "DOM ni paji nk'uko JavaScript iyibona. Hitamo element ukoresheje `document.querySelector()`, uyihindure, kandi witabire ibikorwa ukoresheje `addEventListener()`. Koresha `textContent` (si `innerHTML`) ku nyandiko ziva ku bakoresha kugira ngo wirinde gushyiramo code mbi.",
    "DOM ni ukurasa kama JavaScript inavyouona. Chagua kipengee kwa `document.querySelector()`, kibadilishe, na uitikie vitendo kwa `addEventListener()`. Tumia `textContent` (si `innerHTML`) kwa maandishi ya watumiaji ili kuepuka kuingiza msimbo."),
   (["HTML: `<button id=\"btn\">Click</button> <p id=\"out\"></p>`", "JS: `const btn = document.querySelector(\"#btn\");`", "JS: `btn.addEventListener(\"click\", () => { document.querySelector(\"#out\").textContent = \"Hello!\"; });`", "Put the script at the end of the body, or use `defer`, so the elements exist first."],
    ["HTML : `<button id=\"btn\">Click</button> <p id=\"out\"></p>`", "JS : `const btn = document.querySelector(\"#btn\");`", "JS : `btn.addEventListener(\"click\", () => { document.querySelector(\"#out\").textContent = \"Hello!\"; });`", "Placez le script en fin de body, ou utilisez `defer`, pour que les éléments existent."],
    ["HTML: `<button id=\"btn\">Click</button> <p id=\"out\"></p>`", "JS: `const btn = document.querySelector(\"#btn\");`", "JS: `btn.addEventListener(\"click\", () => { document.querySelector(\"#out\").textContent = \"Hello!\"; });`", "Shyira script ku iherezo rya body, cyangwa ukoreshe `defer`, kugira ngo elements zibanze kubaho."],
    ["HTML: `<button id=\"btn\">Click</button> <p id=\"out\"></p>`", "JS: `const btn = document.querySelector(\"#btn\");`", "JS: `btn.addEventListener(\"click\", () => { document.querySelector(\"#out\").textContent = \"Hello!\"; });`", "Weka script mwisho wa body, au tumia `defer`, ili vipengee viwepo kwanza."])),

_e("js_fetch", ["js_dom_events", "js_arrow_functions", "http_https"],
   ("How do I get data from an API with fetch and async/await?", "Comment récupérer des données d'une API avec fetch et async/await ?", "Nakura nte amakuru kuri API nkoresheje fetch na async/await?", "Ninawezaje kupata data kutoka API kwa fetch na async/await?"),
   ("fetch api|javascript fetch|async await|call an api javascript|get json javascript|promises javascript|fetch data|ajax|http request javascript|await fetch",
    "api fetch|javascript fetch|async await|appeler une api javascript|recuperer du json javascript|promesses javascript|recuperer des donnees|ajax|requete http javascript|await fetch",
    "fetch api|javascript fetch|async await|guhamagara api javascript|gufata json javascript|promises javascript|gukura amakuru|ajax|http request javascript",
    "fetch api|javascript fetch|async await|kuita api javascript|kupata json javascript|promises javascript|kupata data|ajax|ombi la http javascript"),
   ("`fetch()` requests data over HTTP and returns a Promise. With `async`/`await` you can write it like normal step-by-step code. Always check `response.ok` and wrap it in `try/catch` because networks fail.",
    "`fetch()` demande des données par HTTP et renvoie une Promise. Avec `async`/`await` vous l'écrivez comme du code séquentiel. Vérifiez toujours `response.ok` et entourez d'un `try/catch`, car les réseaux échouent.",
    "`fetch()` isaba amakuru kuri HTTP ikagarura Promise. Ukoresheje `async`/`await` wayandika nk'code isanzwe ikurikirana. Burigihe genzura `response.ok` ukoreshe `try/catch` kuko imiyoboro ishobora kunanirwa.",
    "`fetch()` huomba data kupitia HTTP na kurudisha Promise. Kwa `async`/`await` unaweza kuiandika kama msimbo wa kawaida wa hatua kwa hatua. Kagua `response.ok` kila mara na tumia `try/catch` kwa sababu mitandao hushindwa."),
   (["`async function load() {`", "`  try { const res = await fetch(\"https://example.com/api/items\");`", "`    if (!res.ok) throw new Error(\"HTTP \" + res.status); const data = await res.json(); console.log(data);`", "`  } catch (err) { console.error(err); } }` — call it with `load();`"],
    ["`async function load() {`", "`  try { const res = await fetch(\"https://example.com/api/items\");`", "`    if (!res.ok) throw new Error(\"HTTP \" + res.status); const data = await res.json(); console.log(data);`", "`  } catch (err) { console.error(err); } }` — appelez-la avec `load();`"],
    ["`async function load() {`", "`  try { const res = await fetch(\"https://example.com/api/items\");`", "`    if (!res.ok) throw new Error(\"HTTP \" + res.status); const data = await res.json(); console.log(data);`", "`  } catch (err) { console.error(err); } }` — yihamagare ukoresheje `load();`"],
    ["`async function load() {`", "`  try { const res = await fetch(\"https://example.com/api/items\");`", "`    if (!res.ok) throw new Error(\"HTTP \" + res.status); const data = await res.json(); console.log(data);`", "`  } catch (err) { console.error(err); } }` — iite kwa `load();`"])),

_e("js_equality", ["js_variables", "js_arrow_functions", "js_array_methods"],
   ("What is the difference between == and === in JavaScript?", "Quelle différence entre == et === en JavaScript ?", "Itandukaniro rya == na === muri JavaScript ni irihe?", "Tofauti ya == na === katika JavaScript ni ipi?"),
   ("difference between and|== vs ===|double equals triple equals|javascript equality|strict equality|loose equality|javascript typeof|javascript null undefined|equals operator javascript|compare values javascript",
    "== ou ===|double egal triple egal|egalite javascript|egalite stricte|egalite lache|javascript typeof|javascript null undefined|operateur d'egalite javascript|comparer des valeurs javascript",
    "== na ===|kingana kabiri kingana gatatu|equality muri javascript|strict equality|loose equality|javascript typeof|javascript null undefined",
    "== na ===|sawa mara mbili sawa mara tatu|usawa katika javascript|strict equality|loose equality|javascript typeof|javascript null undefined"),
   ("`==` compares after converting types (so `0 == \"0\"` is true), while `===` compares value and type without converting (so `0 === \"0\"` is false). Use `===` almost always; it avoids surprises.",
    "`==` compare après conversion de types (donc `0 == \"0\"` est vrai), tandis que `===` compare valeur et type sans conversion (donc `0 === \"0\"` est faux). Utilisez presque toujours `===` ; cela évite les surprises.",
    "`==` igereranya nyuma yo guhindura ubwoko (bityo `0 == \"0\"` ni ukuri), naho `===` igereranya agaciro n'ubwoko bidahinduwe (bityo `0 === \"0\"` ni ikinyoma). Koresha `===` hafi buri gihe; birinda gutungurwa.",
    "`==` hulinganisha baada ya kubadilisha aina (hivyo `0 == \"0\"` ni kweli), wakati `===` hulinganisha thamani na aina bila kubadilisha (hivyo `0 === \"0\"` ni uongo). Tumia `===` karibu kila mara; huepusha mshangao."),
   (["`5 == \"5\"` → true; `5 === \"5\"` → false.", "`null == undefined` → true; `null === undefined` → false.", "Check a type: `typeof 5` → `\"number\"`.", "Not equal: prefer `!==` over `!=`."],
    ["`5 == \"5\"` → true ; `5 === \"5\"` → false.", "`null == undefined` → true ; `null === undefined` → false.", "Vérifier un type : `typeof 5` → `\"number\"`.", "Différent : préférez `!==` à `!=`."],
    ["`5 == \"5\"` → true; `5 === \"5\"` → false.", "`null == undefined` → true; `null === undefined` → false.", "Kugenzura ubwoko: `typeof 5` → `\"number\"`.", "Kudahwanya: hitamo `!==` aho gukoresha `!=`."],
    ["`5 == \"5\"` → true; `5 === \"5\"` → false.", "`null == undefined` → true; `null === undefined` → false.", "Kuangalia aina: `typeof 5` → `\"number\"`.", "Kutolingana: pendelea `!==` kuliko `!=`."])),

_e("ip_address", ["dns_explained", "router_switch", "wifi_troubleshoot"],
   ("What is an IP address?", "Qu'est-ce qu'une adresse IP ?", "Aderesi ya IP ni iki?", "Anwani ya IP ni nini?"),
   ("ip address|what is an ip address|ipv4|ipv6|private ip|public ip|find my ip|dhcp|subnet mask|default gateway|localhost",
    "adresse ip|qu'est-ce qu'une adresse ip|ipv4|ipv6|ip privee|ip publique|trouver mon ip|dhcp|masque de sous-reseau|passerelle par defaut|localhost",
    "aderesi ya ip|aderesi ya ip ni iki|ipv4|ipv6|ip yihariye|ip rusange|kubona ip yanjye|dhcp|subnet mask|default gateway|localhost",
    "anwani ya ip|anwani ya ip ni nini|ipv4|ipv6|ip ya faragha|ip ya umma|kupata ip yangu|dhcp|subnet mask|default gateway|localhost"),
   ("An IP address is a number that identifies a device on a network so data can reach it. IPv4 looks like `192.168.1.10` (four numbers from 0 to 255); IPv6 is longer and written in hexadecimal. DHCP usually hands out addresses automatically.",
    "Une adresse IP est un numéro qui identifie un appareil sur un réseau pour que les données l'atteignent. IPv4 ressemble à `192.168.1.10` (quatre nombres de 0 à 255) ; IPv6 est plus longue et écrite en hexadécimal. Le DHCP attribue généralement les adresses automatiquement.",
    "Aderesi ya IP ni umubare umenyesha igikoresho kuri network kugira ngo amakuru amugereho. IPv4 isa na `192.168.1.10` (imibare ine kuva kuri 0 kugeza 255); IPv6 ni ndende yandikwa muri hexadecimal. DHCP akenshi itanga aderesi mu buryo bwikora.",
    "Anwani ya IP ni namba inayotambulisha kifaa kwenye mtandao ili data ifike kwake. IPv4 inaonekana kama `192.168.1.10` (namba nne kutoka 0 hadi 255); IPv6 ni ndefu na huandikwa kwa hexadecimal. DHCP kwa kawaida hutoa anwani kiotomatiki."),
   (["Private ranges (inside homes and offices): `10.x.x.x`, `172.16.x.x`–`172.31.x.x`, `192.168.x.x`.", "Your public IP is the one the internet sees, given by your internet provider.", "Find yours on Windows: run `ipconfig`; on Linux or Mac: `ip a` or `ifconfig`.", "`127.0.0.1` (localhost) always means 'this computer'."],
    ["Plages privées (maison, bureau) : `10.x.x.x`, `172.16.x.x`–`172.31.x.x`, `192.168.x.x`.", "Votre IP publique est celle vue par Internet, attribuée par votre fournisseur d'accès.", "Trouvez la vôtre sous Windows : `ipconfig` ; sous Linux ou Mac : `ip a` ou `ifconfig`.", "`127.0.0.1` (localhost) signifie toujours « cet ordinateur »."],
    ["Intera z'ibanga (mu rugo no mu biro): `10.x.x.x`, `172.16.x.x`–`172.31.x.x`, `192.168.x.x`.", "IP rusange ni iyo murandasi ibona, itangwa n'utanga murandasi.", "Menya iyawe kuri Windows: `ipconfig`; kuri Linux cyangwa Mac: `ip a` cyangwa `ifconfig`.", "`127.0.0.1` (localhost) buri gihe bivuga «iyi mudasobwa»."],
    ["Safu za faragha (nyumbani na ofisini): `10.x.x.x`, `172.16.x.x`–`172.31.x.x`, `192.168.x.x`.", "IP yako ya umma ni ile inayoonekana na mtandao, inayotolewa na mtoa huduma wa intaneti.", "Pata yako kwenye Windows: `ipconfig`; kwenye Linux au Mac: `ip a` au `ifconfig`.", "`127.0.0.1` (localhost) daima humaanisha 'kompyuta hii'."])),

_e("dns_explained", ["ip_address", "http_https", "wifi_troubleshoot"],
   ("What is DNS and what does it do?", "Qu'est-ce que le DNS et à quoi sert-il ?", "DNS ni iki kandi ikora iki?", "DNS ni nini na hufanya nini?"),
   ("dns|what is dns|domain name system|dns server|dns not working|dns error|domain name|nslookup|name resolution|change dns",
    "dns|qu'est-ce que le dns|systeme de noms de domaine|serveur dns|dns ne fonctionne pas|erreur dns|nom de domaine|nslookup|resolution de noms|changer le dns",
    "dns|dns ni iki|domain name system|seriveri ya dns|dns ntikora|ikosa rya dns|izina ry'urubuga|nslookup|guhindura dns",
    "dns|dns ni nini|mfumo wa majina ya kikoa|seva ya dns|dns haifanyi kazi|hitilafu ya dns|jina la kikoa|nslookup|kubadilisha dns"),
   ("DNS (Domain Name System) works like the internet's phone book: it turns a name such as `example.com` into the IP address computers actually use. If DNS fails, sites may not open by name even though the connection itself works.",
    "Le DNS (Domain Name System) fonctionne comme l'annuaire d'Internet : il transforme un nom comme `example.com` en adresse IP réellement utilisée par les ordinateurs. Si le DNS échoue, les sites peuvent ne pas s'ouvrir par leur nom alors que la connexion fonctionne.",
    "DNS (Domain Name System) ikora nk'igitabo cy'inimero za telefoni cya murandasi: ihindura izina nka `example.com` aderesi ya IP mudasobwa zikoresha koko. Iyo DNS inaniwe, imbuga zishobora kudafunguka ku izina nubwo uguhuza gukora.",
    "DNS (Domain Name System) hufanya kazi kama kitabu cha simu cha intaneti: hubadilisha jina kama `example.com` kuwa anwani ya IP ambayo kompyuta hutumia kweli. DNS ikishindwa, tovuti zinaweza kutofunguka kwa jina ingawa muunganisho unafanya kazi."),
   (["Test: run `nslookup example.com` and see whether an address comes back.", "If `ping 8.8.8.8` works but names fail, the problem is probably DNS.", "Try another DNS server in your network settings (your provider's, or a public one) and restart the router.", "Flush the cache: `ipconfig /flushdns` on Windows."],
    ["Test : `nslookup example.com` et regardez si une adresse revient.", "Si `ping 8.8.8.8` marche mais pas les noms, le problème est probablement le DNS.", "Essayez un autre serveur DNS dans les réglages réseau (celui du fournisseur ou un public) et redémarrez le routeur.", "Videz le cache : `ipconfig /flushdns` sous Windows."],
    ["Gerageza: `nslookup example.com` urebe niba aderesi igaruka.", "Niba `ping 8.8.8.8` ikora ariko amazina ntakore, ikibazo ni DNS.", "Gerageza indi seriveri ya DNS mu igenamiterere rya network ukore restart ya router.", "Siba cache: `ipconfig /flushdns` kuri Windows."],
    ["Jaribu: `nslookup example.com` na uone kama anwani inarudi.", "Ikiwa `ping 8.8.8.8` inafanya kazi lakini majina hayafanyi, tatizo huenda ni DNS.", "Jaribu seva nyingine ya DNS kwenye mipangilio ya mtandao na uwashe tena router.", "Futa cache: `ipconfig /flushdns` kwenye Windows."])),

_e("osi_model", ["ip_address", "router_switch", "http_https"],
   ("What are the 7 layers of the OSI model?", "Quelles sont les 7 couches du modèle OSI ?", "Ibice 7 by'icyitegererezo cya OSI ni ibihe?", "Tabaka 7 za modeli ya OSI ni zipi?"),
   ("osi model|osi layers|7 layers of osi|seven layers|tcp ip model|network layers|layer 3|layer 2|data link layer|transport layer",
    "modele osi|couches osi|7 couches osi|sept couches|modele tcp ip|couches reseau|couche 3|couche 2|couche liaison de donnees|couche transport",
    "icyitegererezo cya osi|ibice bya osi|ibice 7 bya osi|ibice birindwi|icyitegererezo cya tcp ip|ibice bya network",
    "modeli ya osi|tabaka za osi|tabaka 7 za osi|tabaka saba|modeli ya tcp ip|tabaka za mtandao"),
   ("The OSI model describes networking in seven layers, from bottom to top: 1 Physical, 2 Data Link, 3 Network, 4 Transport, 5 Session, 6 Presentation, 7 Application. Each layer does one job and serves the layer above it.",
    "Le modèle OSI décrit les réseaux en sept couches, de bas en haut : 1 Physique, 2 Liaison de données, 3 Réseau, 4 Transport, 5 Session, 6 Présentation, 7 Application. Chaque couche remplit une tâche et sert la couche au-dessus.",
    "Icyitegererezo cya OSI gisobanura network mu bice birindwi, kuva hasi ujya hejuru: 1 Physical, 2 Data Link, 3 Network, 4 Transport, 5 Session, 6 Presentation, 7 Application. Buri gice gikora umurimo umwe kandi gifasha igice kiri hejuru yacyo.",
    "Modeli ya OSI inaelezea mtandao katika tabaka saba, kutoka chini hadi juu: 1 Physical, 2 Data Link, 3 Network, 4 Transport, 5 Session, 6 Presentation, 7 Application. Kila tabaka lina kazi moja na linalihudumia tabaka la juu yake."),
   (["Layer 1: cables and signals. Layer 2: MAC addresses and switches. Layer 3: IP addresses and routers.", "Layer 4: TCP and UDP, ports. Layers 5–7: sessions, data formats and applications (HTTP, DNS, email).", "Memory aid from the top: All People Seem To Need Data Processing.", "The simpler TCP/IP model groups them into four layers: Link, Internet, Transport, Application."],
    ["Couche 1 : câbles et signaux. Couche 2 : adresses MAC et commutateurs. Couche 3 : adresses IP et routeurs.", "Couche 4 : TCP et UDP, ports. Couches 5–7 : sessions, formats de données et applications (HTTP, DNS, e-mail).", "Aide-mémoire depuis le haut : All People Seem To Need Data Processing.", "Le modèle TCP/IP plus simple les regroupe en quatre couches : Liaison, Internet, Transport, Application."],
    ["Igice 1: insinga n'ibimenyetso. Igice 2: aderesi za MAC na switch. Igice 3: aderesi za IP na router.", "Igice 4: TCP na UDP, ports. Ibice 5–7: sessions, imiterere y'amakuru na porogaramu (HTTP, DNS, imeri).", "Uburyo bwo kwibuka uhereye hejuru: All People Seem To Need Data Processing.", "Icyitegererezo cya TCP/IP cyoroshye kibishyira mu bice bine: Link, Internet, Transport, Application."],
    ["Tabaka 1: nyaya na ishara. Tabaka 2: anwani za MAC na switch. Tabaka 3: anwani za IP na router.", "Tabaka 4: TCP na UDP, ports. Tabaka 5–7: sessions, miundo ya data na programu (HTTP, DNS, barua pepe).", "Msaada wa kukumbuka kutoka juu: All People Seem To Need Data Processing.", "Modeli rahisi ya TCP/IP huzipanga katika tabaka nne: Link, Internet, Transport, Application."])),

_e("router_switch", ["ip_address", "osi_model", "wifi_troubleshoot"],
   ("What is the difference between a router, a switch and an access point?", "Quelle différence entre routeur, commutateur et point d'accès ?", "Itandukaniro rya router, switch na access point ni irihe?", "Tofauti ya router, switch na access point ni ipi?"),
   ("router vs switch|router|switch|access point|hub|what does a router do|what is a switch|modem|network devices|lan wan",
    "routeur ou commutateur|routeur|commutateur|switch|point d'acces|concentrateur|a quoi sert un routeur|qu'est-ce qu'un switch|modem|equipements reseau|lan wan",
    "router na switch|router|switch|access point|hub|router ikora iki|switch ni iki|modem|ibikoresho bya network|lan wan",
    "router na switch|router|switch|access point|hub|router hufanya nini|switch ni nini|modem|vifaa vya mtandao|lan wan"),
   ("A switch connects devices inside one network (LAN) and forwards data using MAC addresses. A router connects different networks, such as your home network and the internet, and forwards data using IP addresses. An access point adds Wi-Fi to a wired network.",
    "Un commutateur (switch) relie des appareils dans un même réseau (LAN) et transmet les données avec les adresses MAC. Un routeur relie des réseaux différents, comme votre réseau domestique et Internet, et transmet avec les adresses IP. Un point d'accès ajoute le Wi-Fi à un réseau filaire.",
    "Switch ihuza ibikoresho biri muri network imwe (LAN) igatanga amakuru ikoresheje aderesi za MAC. Router ihuza network zitandukanye, nk'iy'iwawe na murandasi, igatanga amakuru ikoresheje aderesi za IP. Access point yongera Wi-Fi kuri network y'insinga.",
    "Switch huunganisha vifaa ndani ya mtandao mmoja (LAN) na kusambaza data kwa anwani za MAC. Router huunganisha mitandao tofauti, kama wa nyumbani na intaneti, na kusambaza data kwa anwani za IP. Access point huongeza Wi-Fi kwenye mtandao wa waya."),
   (["A home 'router' is often three devices in one: router, switch and Wi-Fi access point.", "A modem connects you to the internet provider's line; the router shares that connection.", "A hub is an old device that repeats data to every port; switches replaced it.", "LAN = local network; WAN = wide area network such as the internet."],
    ["Le « routeur » domestique réunit souvent trois appareils : routeur, switch et point d'accès Wi-Fi.", "Un modem relie à la ligne du fournisseur ; le routeur partage cette connexion.", "Un hub est un ancien appareil qui répète les données sur tous les ports ; les switchs l'ont remplacé.", "LAN = réseau local ; WAN = réseau étendu comme Internet."],
    ["«Router» yo mu rugo akenshi ni ibikoresho bitatu mu kimwe: router, switch na Wi-Fi access point.", "Modem ihuza n'umurongo w'utanga murandasi; router isangiza uwo muhuza.", "Hub ni igikoresho cya kera gisubiramo amakuru ku miryango yose; switch zayisimbuye.", "LAN = network y'ahantu hamwe; WAN = network nini nka murandasi."],
    ["'Router' ya nyumbani mara nyingi ni vifaa vitatu kwa kimoja: router, switch na Wi-Fi access point.", "Modem huunganisha na laini ya mtoa huduma; router hushiriki muunganisho huo.", "Hub ni kifaa cha zamani kinachorudia data kwenye bandari zote; switch zilichukua nafasi yake.", "LAN = mtandao wa eneo; WAN = mtandao mpana kama intaneti."])),

_e("http_https", ["dns_explained", "check_link", "js_fetch"],
   ("What is the difference between HTTP and HTTPS?", "Quelle différence entre HTTP et HTTPS ?", "Itandukaniro rya HTTP na HTTPS ni irihe?", "Tofauti ya HTTP na HTTPS ni ipi?"),
   ("http vs https|http|https|what is https|ssl|tls|http status codes|404 error|500 error|port 80|port 443|http methods|get and post",
    "http ou https|http|https|qu'est-ce que https|ssl|tls|codes de statut http|erreur 404|erreur 500|port 80|port 443|methodes http|get et post",
    "http na https|http|https|https ni iki|ssl|tls|kode z'imiterere za http|ikosa rya 404|ikosa rya 500|port 80|port 443|get na post",
    "http na https|http|https|https ni nini|ssl|tls|misimbo ya hali ya http|hitilafu ya 404|hitilafu ya 500|port 80|port 443|get na post"),
   ("HTTP is the protocol browsers use to fetch web pages. HTTPS is HTTP carried inside TLS encryption, so others on the network cannot read or alter what you send. HTTPS protects the connection, but it does not prove that a site is honest.",
    "HTTP est le protocole que les navigateurs utilisent pour charger les pages web. HTTPS est du HTTP transporté dans un chiffrement TLS, de sorte que les autres sur le réseau ne peuvent ni lire ni modifier ce que vous envoyez. HTTPS protège la connexion mais ne prouve pas qu'un site est honnête.",
    "HTTP ni protocole browser zikoresha mu gufata impapuro z'urubuga. HTTPS ni HTTP iri mu ibanga rya TLS, bityo abandi bari kuri network batabasha gusoma cyangwa guhindura ibyo wohereje. HTTPS irinda uguhuza ariko ntikerekana ko urubuga ari urwizewe.",
    "HTTP ni itifaki ambayo vivinjari hutumia kupata kurasa za wavuti. HTTPS ni HTTP iliyobebwa ndani ya usimbaji fiche wa TLS, hivyo wengine kwenye mtandao hawawezi kusoma au kubadilisha unachotuma. HTTPS hulinda muunganisho lakini haithibitishi kuwa tovuti ni ya uaminifu."),
   (["Default ports: HTTP 80, HTTPS 443.", "Status codes: 200 OK, 301 moved, 403 forbidden, 404 not found, 500 server error.", "Methods: GET reads data, POST sends data, PUT updates, DELETE removes.", "Enter passwords and payment details only on pages that use HTTPS and whose address you checked."],
    ["Ports par défaut : HTTP 80, HTTPS 443.", "Codes de statut : 200 OK, 301 déplacé, 403 interdit, 404 introuvable, 500 erreur serveur.", "Méthodes : GET lit, POST envoie, PUT met à jour, DELETE supprime.", "Saisissez mots de passe et paiements seulement sur des pages HTTPS dont vous avez vérifié l'adresse."],
    ["Ports zisanzwe: HTTP 80, HTTPS 443.", "Kode z'imiterere: 200 OK, 301 yimuwe, 403 ibujijwe, 404 ntibonetse, 500 ikosa rya seriveri.", "Uburyo: GET asoma, POST yohereza, PUT ivugurura, DELETE ikuraho.", "Andika amagambo y'ibanga n'ayo kwishyura gusa ku mapaji ya HTTPS wagenzuye aderesi yayo."],
    ["Port chaguo-msingi: HTTP 80, HTTPS 443.", "Misimbo ya hali: 200 OK, 301 imehamishwa, 403 imekatazwa, 404 haipatikani, 500 hitilafu ya seva.", "Mbinu: GET husoma, POST hutuma, PUT husasisha, DELETE huondoa.", "Weka nenosiri na malipo kwenye kurasa za HTTPS ulizohakiki anwani yake tu."])),

_e("wifi_troubleshoot", ["router_switch", "dns_explained", "public_wifi"],
   ("My Wi-Fi is connected but there is no internet. What can I do?", "Mon Wi-Fi est connecté mais sans internet. Que faire ?", "Wi-Fi yanjye irahujwe ariko nta murandasi. Nkore iki?", "Wi-Fi imeunganishwa lakini hakuna intaneti. Nifanye nini?"),
   ("wifi not working|connected but no internet|wifi is connected but no internet|wifi connected but no internet|no internet connection|wifi slow|internet slow|can't connect to wifi|wifi keeps disconnecting|fix wifi|router not working|limited connectivity",
    "wifi ne marche pas|wifi connecte mais pas d'internet|pas de connexion internet|wifi lent|internet lent|impossible de se connecter au wifi|wifi se deconnecte|reparer le wifi|routeur ne marche pas|connectivite limitee",
    "wifi ntikora|wifi ihujwe ariko nta murandasi|nta murandasi|wifi itinda|murandasi itinda|sinshobora guhuza na wifi|wifi irivaho|gukosora wifi|router ntikora",
    "wifi haifanyi kazi|wifi imeunganishwa lakini hakuna intaneti|hakuna muunganisho wa intaneti|wifi polepole|intaneti polepole|siwezi kuunganisha wifi|wifi inakatika|kurekebisha wifi|router haifanyi kazi"),
   ("Work from simple to complex: check whether other devices have the same problem, restart the router, then check your own device. If every device is affected, the problem is the router or your internet provider.",
    "Allez du simple au complexe : vérifiez si les autres appareils ont le même problème, redémarrez le routeur, puis vérifiez votre appareil. Si tous les appareils sont touchés, le problème vient du routeur ou du fournisseur d'accès.",
    "Tangira ku byoroshye ujye ku bikomeye: reba niba ibindi bikoresho bifite ikibazo kimwe, ukore restart ya router, hanyuma urebe igikoresho cyawe. Niba bifite byose, ikibazo kiri kuri router cyangwa ku utanga murandasi.",
    "Fanya kutoka rahisi hadi ngumu: angalia kama vifaa vingine vina tatizo hilo, washa router upya, kisha angalia kifaa chako. Ikiwa vifaa vyote vimeathirika, tatizo ni router au mtoa huduma wa intaneti."),
   (["Unplug the router for 30 seconds, plug it back in, and wait a couple of minutes.", "On your device: turn Wi-Fi off and on, or 'forget' the network and reconnect.", "Check that your data bundle or subscription is still active.", "Move closer to the router; if names fail but `ping 8.8.8.8` works, see DNS. Still stuck? Call your provider."],
    ["Débranchez le routeur 30 secondes, rebranchez-le et attendez quelques minutes.", "Sur votre appareil : coupez et rallumez le Wi-Fi, ou « oubliez » le réseau et reconnectez-vous.", "Vérifiez que votre forfait ou abonnement est toujours actif.", "Rapprochez-vous du routeur ; si les noms échouent mais `ping 8.8.8.8` marche, voyez le DNS. Toujours bloqué ? Appelez votre fournisseur."],
    ["Kuramo router mu muriro amasegonda 30, uyisubizemo ugategereze iminota mike.", "Ku gikoresho cyawe: zimya ukongere Wi-Fi, cyangwa «wibagirwe» network wongere uyihuze.", "Reba ko ifatabuguzi cyangwa ama bundle ya murandasi bikiriho.", "Sanga router hafi; niba amazina ananirwa ariko `ping 8.8.8.8` ikora, reba DNS. Biracyananiranye? Hamagara utanga murandasi."],
    ["Chomoa router kwa sekunde 30, iunganishe tena na usubiri dakika chache.", "Kwenye kifaa chako: zima na uwashe Wi-Fi, au 'sahau' mtandao na uunganishe tena.", "Hakikisha kifurushi chako cha data au usajili bado unafanya kazi.", "Sogea karibu na router; majina yakishindwa lakini `ping 8.8.8.8` ikifanya kazi, angalia DNS. Bado umekwama? Piga simu mtoa huduma."])),
]
